  localparam int CLK_PERIOD  = 8;               // 125 MHz
  localparam int PRESCALE_VAL = 16'd5;          // default prescale used in regression

  // -------------------------------------------------------------
  // Clock / reset
  // -------------------------------------------------------------
  reg clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  reg rst = 1'b1;
  initial begin
    #200;
    rst = 1'b0;
    #200;
    rst = 1'b1;
  end

  // -------------------------------------------------------------
  // DUT‑side signals
  // -------------------------------------------------------------
  wire      [7:0] m_axis_tdata;
  wire            m_axis_tvalid;
  wire            busy;
  wire            overrun_error;
  wire            frame_error;

  reg  [15:0]     prescale = PRESCALE_VAL;    // configuration prescale
  reg             rxd = 1'b1;                 // UART receive line driven by TB

  // -------------------------------------------------------------
  // Instantiate uart_rx – name the instance "uart_rx" so coverage can bind
  // -------------------------------------------------------------
  uart_rx uart_rx_inst (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(1'b0),                     // always low → back‑pressure
    .rxd          (rxd),
    .busy         (busy),
    .overrun_error(overrun_error),
    .frame_error  (frame_error),
    .prescale     (prescale)
  );

  // -------------------------------------------------------------
  // Bit‑period length (in clock cycles)
  // -------------------------------------------------------------
  localparam int BIT_CYCLES = PRESCALE_VAL * 8; // 40 clocks

  // -------------------------------------------------------------
  // Task: transmit a frame on rxd
  //   data    – byte to send (LSB first)
  //   stop_low– 1'b1 forces a low stop bit (induces frame_error)
  // -------------------------------------------------------------
  task automatic send_frame(input byte data, input logic stop_low);
    integer i;
    // start bit (low)
    rxd = 1'b0;
    repeat (BIT_CYCLES) @(negedge clk);
    // 8 data bits, LSB first
    for (i = 0; i < 8; i = i + 1) begin
      rxd = data[i];
      repeat (BIT_CYCLES) @(negedge clk);
    end
    // stop bit
    rxd = stop_low ? 1'b0 : 1'b1;
    repeat (BIT_CYCLES) @(negedge clk);
    // return to idle (high) – next call starts a new start bit
  endtask

  // -------------------------------------------------------------
  // Stimulus
  // -------------------------------------------------------------
  initial begin
    // Wait for reset release
    @(negedge rst);
    @(posedge rst);
    #100;

    // ---------------------------------------------------------
    // Frame 1 : 8'h3C with a faulty (low) stop bit → frame_error
    // ---------------------------------------------------------
    send_frame(8'h3C, 1'b1);               // stop bit low forces frame_error
    repeat (5 * BIT_CYCLES) @(negedge clk); // let frame_error be observed

    // ---------------------------------------------------------
    // Frame 2 : 8'hA5 with a correct stop bit → overrun + new word
    // ---------------------------------------------------------
    send_frame(8'hA5, 1'b0);               // proper stop bit
    repeat (10 * BIT_CYCLES) @(negedge clk); // allow overrun to be captured

    $finish;                               // clean termination
  end

endmodule

