  task automatic uart_send_good(input byte unsigned b);
    rxd = 1'b0;                 wait_clks(BIT_CLKS);   // start
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];              wait_clks(BIT_CLKS);   // data, LSB first
    end
    rxd = 1'b1;                 wait_clks(BIT_CLKS);   // stop = 1
