  wire         rx_overrun_error, rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk), .rst(rst),
    .s_axis_tdata(s_axis_tdata), .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata), .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd), .txd(txd),
    .tx_busy(tx_busy), .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error), .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1; wait_clks(5);
    rst = 1'b0; wait_clks(5);
  endtask

  // 8N1 frame on rxd, LSB first, each bit prescale*8 clocks
  task automatic uart_send_byte(input byte unsigned b);
    int bit_clks = int'(prescale) * 8;
    rxd = 1'b0;                   wait_clks(bit_clks);  // start
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];                 wait_clks(bit_clks);
    end
    rxd = 1'b1;                   wait_clks(bit_clks);  // stop
  endtask

  // Frame with a bad (low) stop bit to trigger frame_error
  task automatic uart_send_bad_frame(input byte unsigned b);
    int bit_clks = int'(prescale) * 8;
    rxd = 1'b0;                   wait_clks(bit_clks);  // start
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];                 wait_clks(bit_clks);
    end
    rxd = 1'b0;                   wait_clks(bit_clks);  // bad stop (low)
    rxd = 1'b1;                   wait_clks(bit_clks);  // return to idle
  endtask

  initial begin
    do_reset();
    m_axis_tready = 1'b0;

    // Step 1: Receive 8'h3C with back-pressure held
    uart_send_byte(8'h3C);
    begin
      int timeout = 1000;
      while (!(m_axis_tvalid && (m_axis_tdata == 8'h3C)) && timeout > 0) begin
        @(negedge clk);
        timeout--;
      end
      if (timeout == 0) $fatal(1, "timeout: 8'h3C not valid");
    end
    wait_clks(5);

    // Step 2: Send a bad frame while 8'h3C is still held (frame_error pulses)
    uart_send_bad_frame(8'h00);
    // Wait long enough for the frame error to occur and DUT to return to idle
    wait_clks(1000);

    // Verify 8'h3C is still pending (frame error should not have cleared it)
    if (!(m_axis_tvalid && (m_axis_tdata == 8'h3C) && !m_axis_tready))
      $fatal(1, "8'h3C not still pending after frame error");

    // Step 3: Receive 8'hA5 while 8'h3C is still held (overrun)
    uart_send_byte(8'hA5);
    begin
      int timeout = 1000;
      while (!(m_axis_tdata == 8'hA5) && timeout > 0) begin
        @(negedge clk);
        timeout--;
      end
      if (timeout == 0) $fatal(1, "timeout: 8'hA5 not received");
    end
    wait_clks(10);

    // Release back-pressure and let the pipeline drain
    m_axis_tready = 1'b1;
    wait_clks(10);

    $display("PASS tb: R26 frame_error_then_overrun");
    $finish;
  end

  initial begin
    #100ms;
    $fatal(1, "timeout");
  end

endmodule
